fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Preconditions (optional checks)
    assert!(j < m, "Column index out of bounds");
    assert!(input.len() == n, "Number of rows must be n");
    for row in input {
        assert!(row.len() == m, "All rows must have length m");
    }

    let mut col = Vec::with_capacity(n);
    for i in 0..n {
        col.push(input[i][j]);
    }
    col
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Preconditions (optional checks)
    assert!(input.len() == n, "Number of rows must be n");
    for row in &input {
        assert!(row.len() == m, "All rows must have length m");
    }

    let mut result = Vec::with_capacity(m);
    for j in 0..m {
        result.push(get_column(&input, j, m, n));
    }
    result
}

